using Azure.Storage.Queues;

var queueUri = new Uri("https://demostorageaccount.queue.core.windows.net/email-jobs");
var queueClient = new QueueClient(queueUri, new DefaultAzureCredential());

await queueClient.CreateIfNotExistsAsync();

// Send a message
await queueClient.SendMessageAsync("order-1234");

// Receive messages
QueueMessage[] messages = await queueClient.ReceiveMessagesAsync(maxMessages: 10);
foreach (var message in messages)
{
    Console.WriteLine($"Process: {message.MessageText}");
    await queueClient.DeleteMessageAsync(message.MessageId, message.PopReceipt);
}

public class QueueWorker : BackgroundService
{
    private readonly QueueClient _queue;

    public QueueWorker(QueueClient queue) => _queue = queue;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            var messages = await _queue.ReceiveMessagesAsync(maxMessages: 1, cancellationToken: stoppingToken);
            foreach (var message in messages.Value)
            {
                Console.WriteLine($"Processing: {message.MessageText}");
                // TODO: send email, generate PDF, etc.
                await _queue.DeleteMessageAsync(message.MessageId, message.PopReceipt, stoppingToken);
            }
            await Task.Delay(1000, stoppingToken);
        }
    }
}

// Registration
builder.Services.AddAzureClients(c =>
{
    c.AddQueueServiceClient(builder.Configuration["Azure:Storage:QueueUri"]!);
});
builder.Services.AddHostedService<QueueWorker>();
